/* Only the static training shell is cached. Text stays in localStorage; private meal photos stay in account-scoped IndexedDB. */
const CACHE='mantou-training-shell-v12';
const SHELL=['/','/meal-core.mjs','/meal-store.mjs','/meal-photos.mjs','/meal-zip.mjs','/journal.mjs','/journal-ui.mjs','/journal-sync.mjs','/cloud.mjs','/cloud-config.mjs','/auth-sdk.mjs','/sync-core.mjs','/style.css','/app.mjs','/engine.mjs','/pwa.mjs','/manifest.webmanifest','/icons/icon-192.png','/icons/icon-512.png','/icons/icon-maskable-512.png','/icons/apple-touch-icon.png','/icons/icon.svg'];
const PATHS=new Set(SHELL);
function valid(response,path){if(!response||!response.ok||response.redirected)return false;const type=response.headers.get('content-type')||'';if(path.endsWith('.mjs')||path.endsWith('.js'))return /javascript/.test(type);if(path.endsWith('.css'))return /text\/css/.test(type);if(path.endsWith('.png'))return /image\/png/.test(type);if(path.endsWith('.svg'))return /image\/svg/.test(type);if(path.endsWith('.webmanifest'))return /json|manifest/.test(type);return /text\/html/.test(type);}
self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const path of SHELL){const response=await fetch(new Request(path,{cache:'reload',credentials:'same-origin',redirect:'error'}));if(!valid(response,path))throw Error('Training shell unavailable: '+path);if(path==='/'||path==='/index.html'){const html=await response.clone().text();if(!html.includes('data-training-shell="mantou"'))throw Error('Authentication page is not a training shell');}await cache.put(path,response);}})());});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('mantou-training-shell-')&&key!==CACHE)await caches.delete(key);await self.clients.claim();})());});
self.addEventListener('message',event=>{if(event.data?.type==='ACTIVATE_UPDATE')self.skipWaiting();});
self.addEventListener('fetch',event=>{const req=event.request,url=new URL(req.url);if(req.method!=='GET'||url.origin!==self.location.origin||!PATHS.has(url.pathname)||(url.search&&req.mode!=='navigate'))return;
if(req.mode==='navigate'){event.respondWith((async()=>{const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),3000);try{const response=await fetch(req,{signal:controller.signal});/* Return login/authorization responses online; never cache or replace them. */if(valid(response,url.pathname)){const html=await response.clone().text();if(html.includes('data-training-shell="mantou"')){const cache=await caches.open(CACHE);await cache.put('/',response.clone());await cache.put('/index.html',response.clone());}}return response;}catch{const cache=await caches.open(CACHE);return (await cache.match('/'))||Response.error();}finally{clearTimeout(timer);}})());return;}
event.respondWith((async()=>{const cache=await caches.open(CACHE);const saved=await cache.match(url.pathname);if(saved)return saved;return fetch(req);})());});
